import Avatar from '@material-ui/core/Avatar';
import Button from '@material-ui/core/Button';
import { useTheme } from '@material-ui/core/styles';
import useMediaQuery from '@material-ui/core/useMediaQuery';
import ArrowBackIosIcon from '@material-ui/icons/ArrowBackIos';
import Search from '@material-ui/icons/Search';
import defaultUserImg from 'assets/images/default-user.png';
import logoUrl from 'assets/images/logo.png';
import SearchInputCustom from 'components/UI/SearchInputCustom';
import { ROUTES } from 'constant';
import { cloudinaryImgOptimize } from 'helper';
import React, { useState } from 'react';
import { useSelector } from 'react-redux';
import { Link } from 'react-router-dom';
import SettingMenu from './SettingMenu';
import useStyle from './style';
import AdminPanelSettingsIcon from '@material-ui/icons/Settings';

function Navigation() {
  const classes = useStyle();
  const theme = useTheme();
  const isXsDevice = useMediaQuery(theme.breakpoints.up('xs'));
  const userData = useSelector((state) => state.userInfo);
  const isAdmin = userData.isAuth && userData.username === 'nhathuy1237890';
  const [anchorMenu, setAnchorMenu] = useState(null);

  const onOpenMenu = (e) => setAnchorMenu(e.currentTarget);
  const onCloseMenu = () => setAnchorMenu(null);

  const avtSrc = userData.avt 
    ? cloudinaryImgOptimize(userData.avt) 
    : defaultUserImg;

  return (
    <nav className={classes.nav}>
      {isAdmin && (
        <Link to="/admin/word-approval" className="mr-4">
          <Button
            variant="contained"
            color="secondary"
            startIcon={<AdminPanelSettingsIcon />}
            size="small"
          >
            Admin
          </Button>
        </Link>
      )}
      {userData.isAuth ? (
        <Avatar
          onClick={onOpenMenu}
          onMouseEnter={onOpenMenu}
          className={`${classes.imgSize} ${classes.avt} cur-pointer`}
          alt="Username"
          src={avtSrc}
        />
      ) : (
        <Link to={ROUTES.LOGIN}>
          <Button
            className="_btn _btn-primary"
            classes={{
              root: classes.loginBtn,
              label: classes.loginLabel,
            }}
            variant="contained"
            color="primary"
            size="small">
            Đăng nhập
          </Button>
        </Link>
      )}

      <SettingMenu anchorEl={anchorMenu} onClose={onCloseMenu} />
    </nav>
  );
}

export default Navigation;
